'use strict';
const assert = require('node:assert/strict');
const E = require('../docs/design/prototype-v3-core.js');
let count=0;
function test(name, fn){fn();count++;console.log('✓ '+name);}
function base(balance=1000000, goals=[]){const s=E.seed(true,'2026-11-13');s.base.accounts=[{id:'a',name:'Test',balances:{USD:balance},type:'bank',color:1}];s.base.goals=goals;s.base.salary={account:'a',currency:'USD',amount:300000,day:5,auto:true};return s;}
const g=(id,n,protectedGoal=false,target=2000000,monthly=10000)=>({id,name:id,currency:'USD',target,monthly,holdings:{USD:n},protected:protectedGoal,status:'active',auto:true,icon:'home'});
const out=(s,n)=>E.append(s,{type:'expense',account:'a',currency:'USD',amount:n});
test('free funds before goals',()=>{const s=out(base(1000000,[g('g',500000)]),10000),p=E.project(s);assert.equal(p.goals[0].holdings.USD,500000);assert.equal(E.free(p,s.rates),490000*42);});
test('proportional coverage 90/10',()=>{const s=out(base(1000000,[g('home',900000),g('laptop',100000)]),10000),p=E.project(s);assert.equal(p.goals[0].holdings.USD,891000);assert.equal(p.goals[1].holdings.USD,99000);assert.equal(E.free(p,s.rates),0);});
test('protect goal',()=>{const s=out(base(1000000,[g('home',900000,true),g('laptop',100000)]),10000),p=E.project(s);assert.equal(p.goals[0].holdings.USD,900000);assert.equal(p.goals[1].holdings.USD,90000);});
test('protected shortage remains explicit',()=>{const s=out(base(1000000,[g('home',1000000,true)]),10000),p=E.project(s);assert.equal(E.free(p,s.rates),-10000*42);});
test('monthly total deduplicates detail and repeat',()=>{let s=out(base(300000),40000);s=E.append(s,{type:'month-total',account:'a',currency:'USD',month:'2026-11',amount:150000});assert.equal(E.project(s).accounts[0].balances.USD,150000);const repeated=E.append(s,{type:'month-total',account:'a',currency:'USD',month:'2026-11',amount:150000});assert.equal(repeated.events.length,s.events.length);assert.equal(E.project(repeated).accounts[0].balances.USD,150000);s=out(s,10000);assert.equal(E.project(s).accounts[0].balances.USD,150000);});
test('balance then monthly total no double subtraction',()=>{let s=E.append(base(300000),{type:'balance',account:'a',currency:'USD',amount:150000,asExpense:true});s=E.append(s,{type:'month-total',account:'a',currency:'USD',month:'2026-11',amount:150000});assert.equal(E.project(s).accounts[0].balances.USD,150000);});
test('expense correction restores goals and free funds',()=>{let s=out(base(300000,[g('pc',20000)]),290000);s=E.edit(s,s.events[0].id,{amount:250000});const p=E.project(s);assert.equal(p.accounts[0].balances.USD,50000);assert.equal(p.goals[0].holdings.USD,20000);assert.equal(E.free(p,s.rates),30000*42);});
test('purchase 450 from 500 frees 50 exactly once',()=>{let s=E.append(base(50000,[g('pc',50000,false,50000)]),{type:'purchase',goalId:'pc',account:'a',currency:'USD',amount:45000});const p=E.project(s);assert.equal(p.accounts[0].balances.USD,5000);assert.equal(E.pool(p,s.rates),0);assert.equal(E.free(p,s.rates),5000*42);assert.throws(()=>E.append(s,{type:'purchase',goalId:'pc',account:'a',currency:'USD',amount:100}));});
test('salary and last capped contribution only once',()=>{let s=base(0,[g('pc',45000,false,50000,10000)]);s.base.accounts[0].balances.USD=45000;s=E.append(s,{type:'month',month:'2026-11'});const p=E.project(s);assert.equal(p.goals[0].holdings.USD,50000);const p2=E.project(E.append(s,{type:'month',month:'2026-11'}));assert.equal(p2.accounts[0].balances.USD,p.accounts[0].balances.USD);});
test('same currency transfer preserves total',()=>{let s=base(100000);s.base.accounts.push({id:'b',name:'Cash',balances:{USD:0},type:'cash',color:2});s=E.append(s,{type:'transfer',account:'a',to:'b',currency:'USD',toCurrency:'USD',amount:30000,received:30000,fee:0});const p=E.project(s);assert.equal(p.accounts[0].balances.USD,70000);assert.equal(p.accounts[1].balances.USD,30000);assert.equal(E.total(p,s.rates),100000*42);});
test('negative balances are rejected',()=>assert.throws(()=>out(base(10000),20000)));
test('historical checkpoint blocks unsafe edit',()=>{let s=out(base(300000),10000);s=E.append(s,{type:'balance',account:'a',currency:'USD',amount:280000,asExpense:true});assert.throws(()=>E.edit(s,s.events[0].id,{amount:5000}));});
test('rate change does not rewrite historical coverage',()=>{const s=out(base(100000,[g('a',100000)]),10000), before=E.project(s).goals[0].holdings.USD;const changed={...s,rates:{...s.rates,USD:50}};assert.equal(E.project(changed).goals[0].holdings.USD,before);});
test('protection change does not rewrite prior expense',()=>{let s=out(base(100000,[g('a',100000)]),10000);s=E.append(s,{type:'goal-settings',goalId:'a',changes:{protected:true}});assert.equal(E.project(s).goals[0].holdings.USD,90000);});
console.log(count+' financial prototype checks passed.');
